import{j as e}from"./index-BwvIQEpx.js";import{S as t,s as n}from"./ServicePage-v33VhXKA.js";import"./Breadcrumbs-CmKNBEjS.js";import"./triangle-alert-Bazl3mf_.js";const a={path:"/services/ai-voice-agent-development",icon:"voice",h1:"AI Voice Agent Development",valueProp:"Voice agents that hold a real conversation inside your website or app — listening, being interrupted, asking the next sensible question, and handing over to a person when they should.",heroHighlights:["Two-way spoken conversation in the browser or in your mobile app","Interruption and turn-taking handled, not scripted menus","Escalation to your team, and transcripts only with consent"],intro:['A voice agent is not a phone menu that learned some vocabulary. There is no numbered list, no "press one", and no fixed path: the visitor talks, the agent listens continuously, understands what was meant rather than matching a keyword, and can be interrupted mid-sentence the way a person can.',"We build these as products, not demos. The website you are reading runs one — an agent that speaks with visitors, gathers what a project needs and produces a preliminary estimate — so the engineering described below is work we operate and maintain rather than something assembled for a brochure."],problems:{eyebrow:"Why teams want voice",heading:"The problems a voice agent is brought in to solve",intro:"Voice is worth the extra engineering when typing is the obstacle, or when the conversation itself is the product.",items:[{title:"Enquiries arrive outside working hours and go cold",body:"Someone with intent lands on your site at eleven at night, finds a contact form, and leaves. A voice agent can hold the conversation immediately and pass a structured summary to your team for the morning."},{title:"Forms collect fields but not context",body:"A form gets a name and a budget range. A conversation gets what the project actually is, what has already been tried, and which constraints are non-negotiable — because it can ask the follow-up question."},{title:"Your team repeats the same first call",body:"The opening qualification call is largely identical every time. Automating that first pass lets people spend their time on the conversations where judgement matters."},{title:"Typing is the wrong interface for the situation",body:"Hands busy, on the move, on a phone, or simply faster at speaking than typing. In field, accessibility and mobile contexts, voice is not a novelty — it is the only usable input."},{title:"The old phone menu is actively losing customers",body:"Rigid IVR trees frustrate people into hanging up or pressing zero. Replacing that logic with a system that understands intent removes the tree entirely."}]},useCases:{eyebrow:"What it is used for",heading:"Where voice agents work well",intro:"Each of these is a conversation with a defined goal — which is what makes it automatable without becoming frustrating.",items:[{title:"Requirement collection",body:"Walking someone through what they need — scope, users, integrations, constraints — and recording it as structured data your team can act on, not as a paragraph someone has to re-read."},{title:"Lead qualification",body:"Establishing fit, timeline and decision process in a natural conversation, then scoring and routing the enquiry to the right person with the context already attached."},{title:"Appointment and consultation booking",body:"Checking availability, confirming details and creating the booking during the conversation, with confirmation sent afterwards through your existing channels."},{title:"Guided onboarding and product help",body:"A spoken walkthrough for a new user, answering questions from your documentation while they are actually in the product rather than reading a help centre."},{title:"Hands-free operational assistants",body:"Field and warehouse staff asking for a record, logging a status or dictating a note without stopping to find a screen."},{title:"Accessible interfaces",body:"A spoken route through a service for users who cannot comfortably read or type, offered alongside the visual interface rather than instead of it."}]},capabilities:{eyebrow:"How it works",heading:"What we build into a voice agent",intro:"A voice agent is a real-time pipeline with a language model in the middle. Every stage below is one we implement and tune per project.",groups:[{title:"The real-time speech pipeline",body:"Audio in, audio out, fast enough that the pause does not feel like a fault.",items:["Voice activity detection, so the agent knows when speech starts and stops","Streaming speech-to-text with punctuation and partial results","Language-model reasoning over the conversation so far","Text-to-speech with a voice chosen to suit your brand","Latency budgeting across the whole loop, because delay is what breaks the illusion"]},{title:"Turn-taking and interruption",body:"The part that separates a conversation from a recital, and the part most demos skip.",items:["Barge-in: the visitor can interrupt and the agent stops talking","Confirmed-turn handling, so the agent does not answer half a sentence","Pacing tuned for the context, slower where accuracy matters","A single gentle prompt after a long silence, rather than repeated nagging","Recovery when audio drops or a device is switched mid-conversation"]},{title:"Structured conversation and tools",body:"What the agent is allowed to do is defined in code, not left to the model’s discretion.",items:["Typed conversation state the model can only write through a validated schema","A narrow set of permitted tools, each with a strict input contract","Business calculations performed server-side, never by the model","Deterministic routing for openings and decisions that must be repeatable","Grounding in an approved body of company facts, with refusal outside it"]},{title:"Handover and human escalation",body:"The agent’s most important behaviour is knowing when to stop being the agent.",items:["A visitor can ask for a human at any point and be taken there","Automatic escalation on repeated misunderstanding or a sensitive topic","Structured summary passed to your team with the conversation context","Callback or meeting booking as the handover, where live transfer is not available","Clear disclosure that the visitor is speaking with an AI agent"]},{title:"Channels and integration",body:"Voice agents we build run in the browser and inside apps over an internet connection.",items:["Website widget and embedded in-product experiences","iOS and Android application integration","Real-time audio transport with reconnect handling","CRM, helpdesk and internal-system integration for what the conversation produces","Email, messaging and webhook notification to your team"]},{title:"Operations, monitoring and cost control",body:"A live voice agent consumes metered services every second it is speaking.",items:["Session length and concurrency limits enforced server-side","Per-session cost visibility across speech and model usage","Audit events for guard triggers, tool calls and escalations","Quality review of sampled conversations after launch","A defined fallback — a form or a callback — when a provider is unavailable"]}]},approach:{eyebrow:"How we work",heading:"Our approach to voice agents",intro:"Voice raises the cost of every mistake: there is no scrollback, no page to re-read, and a wrong turn is heard as incompetence rather than seen as a bug.",points:["The goal of the conversation is defined first. An agent with no completion state talks in circles.","The agent is grounded in an approved, version-controlled set of company facts and is built to say it does not know rather than improvise.","The model interprets speech; deterministic code performs every calculation and every write to your systems.","Latency is treated as a feature: we measure the full loop and tune it, because a two-second gap reads as a broken line.","Visitor speech is untrusted input. Tool schemas stay narrow, actions stay whitelisted, and likely manipulation attempts are flagged and audited.","Every agent discloses that it is an AI, and offers a route to a person from the first exchange."]},process:{eyebrow:"Discovery through operation",heading:"How a voice agent project runs",intro:"Scripting is a small part of it. Most of the work is state design, integration and tuning against real speech.",steps:[{title:"Discovery and conversation design",body:"We define what the conversation is for, what it must collect, and what a successful ending looks like.",points:["The goal of the conversation and its completion criteria","The facts the agent may state, and where they come from","Information to be collected, and its structure","Escalation triggers and the human path behind them","Language, tone and disclosure requirements agreed in writing"]},{title:"Architecture and interaction design",body:"Voice needs its own interface thinking: what the visitor sees while listening, speaking and waiting.",points:["Real-time audio transport and session architecture","Typed conversation state and validated tool contracts","Microphone permission, device selection and audio-recovery flows","Visual state for listening, thinking and speaking, plus a text fallback","Consent and disclosure surfaces designed before build, not bolted on"]},{title:"Development and integrations",body:"The pipeline is assembled, grounded and connected to the systems that receive what the conversation produces.",points:["Speech, reasoning and synthesis pipeline with provider abstraction","Turn-taking, interruption and silence handling","Knowledge grounding and refusal behaviour","CRM, email and internal-system integration","Server-side session, rate and budget limits"]},{title:"Testing and quality assurance",body:"Tested against how people actually speak — accents, background noise, half-sentences and changed minds.",points:["Scripted and unscripted conversation testing with real voices","Accent, noise and poor-connection scenarios","Interruption, silence and mid-conversation device changes","Adversarial testing, including attempts to push the agent off its brief","Latency and cost measurement across full sessions"]},{title:"Launch, monitoring and tuning",body:"The first weeks of real conversations teach more than any amount of internal testing.",points:["Phased launch, often to a limited audience first","Review of sampled conversations against the conversation goal","Monitoring of completion rates, escalations and flagged events","Prompt, grounding and pacing adjustments based on real transcripts","Ongoing support for provider changes and new requirements"]}]},integration:{eyebrow:"Integration",heading:"Connecting a voice agent to your business",intro:"A conversation is only valuable if what it produces reaches the right system. That is normal integration work and is scoped explicitly.",points:["Embedded in your website, web application or mobile app over an internet connection, using your existing authentication where the agent is for signed-in users.","Structured output — requirements, qualification answers, bookings — written into your CRM, helpdesk or internal tools through their APIs.","Email, messaging or webhook notifications so your team is alerted while the enquiry is still warm.","Calendar and scheduling integration where the conversation ends in an appointment.","Transcripts and summaries stored under your retention policy, and only where the visitor has consented.","Deployment into your cloud accounts, with provider credentials held in your secret store rather than ours."]},limitations:{eyebrow:"Honest limits",heading:"What a voice agent will not do",intro:"Voice is the AI capability most often oversold. These are the constraints we state before a project starts.",points:["These agents run over an internet connection in a browser or an app. We do not offer telephone calling: no dialling out, no receiving calls on a phone number, and no PSTN or SIP integration. If you need telephony, that is a separate build with a telephony provider and should be scoped as one.","Speech recognition is imperfect. Strong accents, background noise, unusual proper nouns and poor connections all produce errors, which is why the agent confirms anything important before acting on it.","A language model can still produce a wrong answer. Grounding and refusal behaviour reduce this substantially; they do not remove it.","Multilingual conversation is possible but is custom scope, not a switch. Each language needs its own recognition and synthesis configuration, its own grounding content and its own testing. Our own agent runs its consultation mode in English today.","Real-time voice consumes metered services continuously, so cost scales with conversation minutes rather than with page views.","Latency depends on network conditions and provider availability, and neither is fully within our control.","The agent will not make binding commitments — prices, contracts or approvals — on your behalf. Those route to a person."],oversight:{title:"Human oversight we design in",points:["A route to a human offered from the start, and honoured whenever it is asked for","Automatic escalation on repeated misunderstanding or sensitive topics","Anything commercially binding held for human confirmation","Sampled conversation review after launch, feeding back into tuning","Audit events for flagged inputs, tool calls and escalations"]},note:"Transcripts and recordings are only captured where the visitor has given consent, and consent state travels with the record so your team can see it. Disclosure that the visitor is speaking with an AI agent is built in and is not something we will remove on request."},engagement:{eyebrow:"Working together",heading:"Engagement options for voice agents",intro:"Voice agents need tuning against real conversations, so most clients move to an ongoing arrangement after launch.",options:[{name:"Pilot agent",body:"A single conversation goal — qualification, booking or requirement collection — built, integrated and launched to a limited audience so the value can be judged on real conversations.",bestFor:"Best for proving voice fits your audience."},{name:"Full agent build",body:"Multiple conversation goals, deeper system integration, escalation paths and the operational tooling your team needs to run it.",bestFor:"Best once a pilot has shown the pattern works."},{name:"Voice agent operations",body:"Monthly capacity for transcript review, prompt and grounding updates, provider changes, cost tuning and incident response.",bestFor:"Best for an agent handling live enquiries."}]},security:{eyebrow:"Security and privacy",heading:"Handling voice data responsibly",intro:"Voice is personal data, and a conversation often contains more than a form would. These are the practices we apply.",points:["Explicit consent before any transcript or recording is stored, with the consent state kept alongside the record","Clear disclosure at the start of the conversation that the visitor is speaking with an AI agent","Encrypted audio transport, and encrypted storage for anything retained","Provider credentials held server-side; the client receives only a short-lived, scoped session token","The conversation worker given no database credentials — it reaches your systems through a narrow, authenticated interface","Visitor speech treated as untrusted input, with likely manipulation attempts flagged and audited","Session, concurrency and budget limits enforced server-side where a client cannot raise them","Configurable retention and deletion for transcripts, summaries and audio"],note:"We hold no certification and cannot warrant a system secure. Voice conversations frequently capture personal data, so where you operate under a specific privacy regime, raise it during discovery: consent wording, retention periods and data location are design decisions and are far cheaper to set before launch."},faqs:[{question:"How is this different from an IVR phone menu?",answer:"An IVR is a fixed decision tree: it plays options, waits for a keypress or a matched keyword, and moves to the next node. A voice agent has no tree. It listens continuously, works out intent from natural speech, keeps track of what has already been said, can be interrupted mid-sentence, and asks follow-up questions that were never scripted. It also knows when it is out of its depth and escalates instead of looping."},{question:"Can the agent make or take phone calls?",answer:"No. The voice agents we build run over an internet connection inside a website or a mobile app. We have not implemented telephony, so we do not claim it: no outbound dialling, no inbound phone number, no PSTN or SIP. If phone calling is a requirement, it is a separate integration with a telephony provider and we would scope it as its own piece of work."},{question:"Can it speak other languages?",answer:"It can, but treat it as custom scope rather than a setting. Each language needs its own speech recognition and synthesis configuration, its own grounded content, and its own testing with native speakers — and quality varies by language. We scope and price the languages you actually need rather than claiming everything."},{question:"What happens when the agent does not understand?",answer:"It asks for clarification once, rephrasing rather than repeating. If misunderstanding continues, or the topic is one we have marked as sensitive, it escalates: offering a person, booking a callback or handing over a structured summary to your team. Looping silently is the failure mode we design hardest against."},{question:"Are conversations recorded?",answer:"Only with consent. Transcripts and recordings are opt-in, the consent state is stored with the record so your team can see it, and retention is configured to your policy. Disclosure that the visitor is talking to an AI is built into the opening and is not removable."},{question:"What does it cost to run?",answer:"Cost scales with conversation minutes rather than traffic, because speech recognition, model reasoning and speech synthesis are all metered. We build in session limits, concurrency caps and per-session cost visibility, and estimate a range during discovery once the expected conversation length and volume are known."}],markets:{title:"Markets we deploy voice agents into",intro:"A voice agent talks to your callers in your market's accents, phrasing and business hours, so the market pages below cover call-hour coverage and consent expectations rather than pretending an Indian team answers the phone locally."},related:[{path:"/services/ai-development",label:"AI Development",blurb:"The AI pillar: assistants, retrieval, structured AI workflows and the engineering around them."},{path:"/services/conversational-ai-development",label:"Conversational AI Development",blurb:"The same conversation design applied to chat channels, or to chat and voice together."},{path:"/services/ai-video-consultation-agents",label:"AI Video Consultation Agents",blurb:"Voice plus an avatar-led room, live transcript, chat and a structured meeting summary."},{path:"/services/ai-automation-integration",label:"AI Automation & Integration",blurb:"Turning what a conversation collects into records, notifications and workflow steps."},{path:"/services/mobile-app-development",label:"Mobile App Development",blurb:"Embedding a voice agent inside an iOS or Android product, with the permissions it needs."},{path:"/services/web-application-development",label:"Web Application Development",blurb:"The web product a voice agent usually sits inside, and the admin screens behind it."}],cta:{title:"Want to hear what a voice agent could do for you?",body:"There is one on this site — start a consultation and talk to it. Or get an indicative estimate for your own, and send the details to the team."}},d=()=>e.jsx(t,{content:n(a)});export{d as default};
